{
  "title": "The Glass Diver's Rescue",
  "gate_token": "nE-2LN_JszzZd7Cy27hmVA",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party arrives at the ruined city gates.",
      "visual_description": "Crumbling stone gates flanked by tattered royal banners, a massive portcullis half-lifted, and empty guard posts overgrown with vines.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 2,
      "caption": "Mara consults her map in a broken courtyard.",
      "visual_description": "A cracked cobblestone courtyard littered with fallen columns; Mara traces a faded route on her map while the oracle lamp flickers nearby.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox scouts a narrow alley ahead.",
      "visual_description": "A tight alley between collapsed buildings, the tin fox's blue eyes reflecting off wet stones as it sniffs the air.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The oracle lamp warns of a cursed tower.",
      "visual_description": "The lamp's eye glows red as it bobs toward a leaning tower wrapped in thorny vines, and the glass diver peers through a cracked window.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The sleeping tax collector blocks a doorway.",
      "visual_description": "A wooden door half off its hinges, the tax collector slumped against the frame with a ledger over his face, papers scattered at his feet.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 6,
      "caption": "Mara negotiates a path past the tax collector.",
      "visual_description": "Mara gently lifts a stamped paper from the sleeper's sleeve, revealing a hidden passage on a map; the tin fox whirs patiently.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "The glass diver swims through a window into a locked treasury.",
      "visual_description": "A mirrored pane transforms into liquid as the glass diver passes through, emerging into a dusty chamber with empty shelves.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Rumors of a dragon echo in a market square.",
      "visual_description": "An empty market square with overturned carts and burnt cloth; the oracle lamp's flame trembles as a low roar rumbles nearby.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "The tin fox finds a hidden mechanism.",
      "visual_description": "The fox's paw presses a loose cobblestone, revealing a brass lever that clicks; a section of wall grinds open.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "Armored patrols march through the main avenue.",
      "visual_description": "A wide avenue lined with statues, a column of figures in enameled armor clanking in unison, their visors blank.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "The party hides behind a collapsed throne.",
      "visual_description": "A toppled stone throne in a roofless hall, the group crouching as patrol echoes pass; the oracle lamp dims to a whisper.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "A magic door appears in a dead-end corridor.",
      "visual_description": "A door of swirling light set into a blank wall, its surface rippling with symbols; the glass diver reaches out to touch it.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "Mara deciphers the door's riddle.",
      "visual_description": "Mara traces the glowing symbols with ink-stained fingers, muttering coordinates while the tin fox watches alertly.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The oracle lamp sacrifices its flame to open the door.",
      "visual_description": "The lamp's eye flares brightly, its flame leaping to the door's center, burning away the lock; the lamp dims to a ember.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "The party enters a hidden garden courtyard.",
      "visual_description": "A walled garden with an overgrown fountain and a single intact royal banner; the glass diver sees a mirror pool at the center.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "The glass diver retrieves a memory shard from the pool.",
      "visual_description": "The diver plunges into the mirrored pool, surfacing with a crystalline shard that glows with faint light.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 17,
      "caption": "Armored patrols converge on the garden.",
      "visual_description": "The garden gate splinters as patrols break through; Mara folds her map and the tin fox's tail spins rapidly.",
      "characters": ["mara_the_cartographer", "tin_fox", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "The group escapes across a crumbling bridge.",
      "visual_description": "A stone bridge spanning a chasm, its center sagging; the party runs as stones fall, the glass diver carrying the shard, the lamp's ember glowing faintly.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

